function baseMaterials(mesh){let state=materialState.get(mesh);if(!state){const current=Array.isArray(mesh.material)?mesh.material:[mesh.material];state={base:current.map(m=>m.clone()),texture:null,shader:''};materialState.set(mesh,state);}return state;}
const DEFAULT_SHADER_VERTEX=`varying vec2 vUv;varying vec3 vNormal;varying vec3 vViewPosition;void main(){vUv=uv;vNormal=normalize(normalMatrix*normal);vec4 mvPosition=modelViewMatrix*vec4(position,1.0);vViewPosition=-mvPosition.xyz;gl_Position=projectionMatrix*mvPosition;}`;
function rebuildMaterial(mesh){const info=baseMaterials(mesh),shader=mesh.userData.shaderCode||'',vertex=mesh.userData.vertexShader||'',full=/\bvoid\s+main\s*\(/.test(shader),fullVertex=/\bvoid\s+main\s*\(/.test(vertex),fresh=info.base.map(base=>{if(full||fullVertex){const declarations=`precision highp float;\nvarying vec2 vUv;\nvarying vec3 vNormal;\nvarying vec3 vViewPosition;\nuniform float uTime;\nuniform vec3 uBaseColor;\nuniform sampler2D uTexture;\nuniform float uHasTexture;\n`;const defaultFragment=`void main(){vec4 c=vec4(uBaseColor,1.0);if(uHasTexture>0.5)c*=texture2D(uTexture,vUv);gl_FragColor=c;}`;const m=new THREE.ShaderMaterial({vertexShader:fullVertex?vertex:DEFAULT_SHADER_VERTEX,fragmentShader:declarations+(full?shader:defaultFragment),uniforms:{uTime:{value:0},uBaseColor:{value:base.color?.clone?.()||new THREE.Color(0xffffff)},uTexture:{value:info.texture||new THREE.Texture()},uHasTexture:{value:info.texture?1:0}},side:base.side,transparent:base.transparent,depthWrite:base.depthWrite,depthTest:base.depthTest});m.customProgramCacheKey=()=>`mobiforge-full:${vertex}:${shader}:${!!info.texture}`;return m;}const m=base.clone();if(info.texture){m.map=info.texture;m.needsUpdate=true;}if(shader.trim()){m.onBeforeCompile=program=>{program.fragmentShader=program.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>\\n// MobiForge GLSL snippet: diffuseColor is available\\n${shader}\\n`);};m.customProgramCacheKey=()=>`mobiforge-glsl:${shader}`;m.needsUpdate=true;}return m;});const old=mesh.material;mesh.material=Array.isArray(old)?fresh:fresh[0];for(const m of (Array.isArray(old)?old:[old]))if(m&&!info.base.includes(m))m.dispose();}
function applyShader(target){if(!target)return;const code=target.userData.shaderCode||'',vertex=target.userData.vertexShader||'';if(code.length+vertex.length>48000){toast('El shader GLSL supera 48 KB');return;}try{state.shaderError='';target.traverse(mesh=>{if(mesh.isMesh&&!mesh.userData.helper)rebuildMaterial(mesh);});if(state.renderer)state.renderer.compile(state.scene,state.camera);if(!state.shaderError)$('#luaResult').textContent=code.trim()||vertex.trim()?'GLSL aplicado al objeto':'Shader retirado';}catch(err){$('#luaResult').textContent=`Shader: ${err.message}`;toast('No se pudo aplicar el GLSL');}}
async function applyImageFile(file,target){if(!file.type.startsWith('image/'))throw new Error('Elige un archivo de imagen');if(file.size>30*1024*1024)throw new Error('La imagen debe pesar menos de 30 MB');const url=URL.createObjectURL(file);try{const texture=await new Promise((resolve,reject)=>new THREE.TextureLoader().load(url,resolve,undefined,reject));texture.colorSpace=THREE.SRGBColorSpace;texture.flipY=true;texture.needsUpdate=true;target.traverse(mesh=>{if(mesh.isMesh&&!mesh.userData.helper){const info=baseMaterials(mesh);info.texture=texture;mesh.userData.imageDataURL=null;rebuildMaterial(mesh);}});state.imageUrls.push(url);state.imageTextures.push(texture);target.userData.imageName=file.name;$('#luaResult').textContent=`Imagen aplicada: ${file.name}`;if(file.size<=1024*1024){const reader=new FileReader();reader.onload=()=>{target.userData.imageDataURL=String(reader.result||'');};reader.readAsDataURL(file);}else target.userData.imageDataURL='';}catch(err){URL.revokeObjectURL(url);throw err;}}
async function applyImageData(dataUrl,target){const texture=await new Promise((resolve,reject)=>new THREE.TextureLoader().load(dataUrl,resolve,undefined,reject));texture.colorSpace=THREE.SRGBColorSpace;state.imageTextures.push(texture);target.traverse(mesh=>{if(mesh.isMesh&&!mesh.userData.helper){const info=baseMaterials(mesh);info.texture=texture;rebuildMaterial(mesh);}});}
function setCodeMode(mode,target=state.scriptTarget||data.selected){state.codeMode=mode==='glsl'?'glsl':'lua';state.codeStage=state.codeStage||'fragment';document.querySelectorAll('[data-code-mode]').forEach(b=>b.classList.toggle('active',b.dataset.codeMode===state.codeMode));const overlay=$('#scriptOverlayEditor'),vertex=$('#scriptVertexEditor'),stage=state.codeStage||'fragment';overlay.placeholder=state.codeMode==='glsl'?(stage==='vertex'?'// Vertex GLSL: main(), position, modelViewMatrix, projectionMatrix':'// Fragment GLSL: main(), vUv, vNormal, vViewPosition, uTime, uBaseColor, uTexture'):'-- Lua para este objeto';$('.lua-layer').classList.toggle('hidden',state.codeMode==='glsl'&&stage==='vertex');$('.vertex-layer').classList.toggle('hidden',state.codeMode!=='glsl'||stage!=='vertex');overlay.value=target?(state.codeMode==='glsl'?(stage==='fragment'?(target.userData.shaderCode||''):(target.userData.vertexShader||'')):(target.userData.scriptText||'')):'';vertex.value=target?(target.userData.vertexShader||''):'';syncHighlight('scriptOverlayEditor','scriptOverlayHighlight',state.codeMode);syncHighlight('scriptVertexEditor','scriptVertexHighlight','glsl');document.querySelectorAll('[data-code-stage]').forEach(b=>b.classList.toggle('active',b.dataset.codeStage===stage));$('#scriptOverlay').classList.toggle('shader-mode',state.codeMode==='glsl');const hint=$('.code-mode-hint');if(hint)hint.textContent=state.codeMode==='lua'?'Lua del runtime del objeto seleccionado':'GLSL '+(stage==='vertex'?'Vertex':'Fragment')+' · guarda fragmentos o shaders completos';if($('#scriptTitle'))$('#scriptTitle').textContent=`${state.codeMode==='glsl'?`GLSL ${stage==='vertex'?'Vertex':'Fragment'}`:'Lua'} · ${state.scriptTarget?.name||target?.name||'objeto'}`;}
function syncCodeEditors(target){if(!target)return;const overlay=$('#scriptOverlayEditor'),vertex=$('#scriptVertexEditor');if(state.scriptTarget===target&&document.activeElement!==overlay&&document.activeElement!==vertex){if(state.codeMode==='glsl'){if(state.codeStage==='vertex')vertex.value=target.userData.vertexShader||'';else overlay.value=target.userData.shaderCode||'';}else overlay.value=target.userData.scriptText||'';}}
function applySelectedCode(target){if(!target)return;const overlay=$('#scriptOverlayEditor'),vertex=$('#scriptVertexEditor');if(state.codeMode==='glsl'){if(state.codeStage==='vertex')target.userData.vertexShader=vertex.value;else target.userData.shaderCode=overlay.value;applyShader(target);}else executeLua(target.userData.scriptText||'',target,false,false);}
function setObjectScript(target,text){if(!target)return;if(state.codeMode==='glsl')target.userData.shaderCode=text;else target.userData.scriptText=text;if(data.selected===target)data.script=target.userData.scriptText||'';syncCodeEditors(target);}
function openScriptMode(target=data.selected){if(!target){toast('Selecciona un objeto para editar su código');return;}state.scriptTarget=target;ensureScriptForSelectedFor(target);$('#scriptOverlay').classList.remove('hidden');setCodeMode(state.codeMode,target);$('#scriptTitle').textContent=`${state.codeMode==='glsl'?'Shader GLSL':'Lua'} · ${target.name}`;document.querySelectorAll('.main-modes .mode-tab').forEach(b=>b.classList.toggle('selected',b.dataset.tool==='script'));$('#bottomStatus').textContent=`Script · ${target.name}`;}
function ensureScriptForSelectedFor(target){if(!target.userData.scriptText)target.userData.scriptText=`-- Script de ${target.name}\nfunction start()\n  print("Listo: " .. node.name)\nend\nfunction update(dt)\nend`;return target;}
function closeScriptMode(){const overlay=$('#scriptOverlay');overlay.classList.add('hidden');document.querySelectorAll('.main-modes .mode-tab').forEach(b=>b.classList.toggle('selected',b.dataset.tool==='3d'));state.scriptTarget=null;state.codeMode='lua';$('#bottomStatus').textContent='Edición · listo';}
function refreshOutline(target=data.selected,customColor=null,customScale=1.035){for(const n of state.outlineNodes){if(n.parent)n.parent.remove(n);n.material?.dispose?.();}state.outlineNodes=[];if(!state.outlineEnabled||!target)return;target.traverse(mesh=>{if(!mesh.isMesh||mesh.userData.helper||mesh.isSkinnedMesh)return;const material=new THREE.MeshBasicMaterial({color:customColor||0x73b8ff,side:THREE.BackSide,depthTest:true,depthWrite:false,transparent:false});const shell=new THREE.Mesh(mesh.geometry,material);shell.name='Outline';shell.userData.helper=true;shell.scale.setScalar(customScale);shell.renderOrder=2;shell.raycast=()=>{};mesh.add(shell);state.outlineNodes.push(shell);});state.outlineTarget=target;state.outlineColor=customColor||state.outlineColor||0x73b8ff;state.outlineScale=customScale;}
function addCustomCard(name) { const card=document.createElement('button');card.className='project-card';card.innerHTML='<div class="thumb tps"><span>3D</span><div class="figure">✦</div></div><b></b><small>Proyecto propio · escena 3D</small><i>ABRIR PROYECTO　›</i>';card.querySelector('b').textContent=name;card.onclick=()=>{data.customName=name;showEditor('custom');};$('.project-grid').append(card); }
JSON.parse(localStorage.getItem('mf_projects')||'[]').forEach(addCustomCard);
$('#newProject').onclick=()=>{const n=prompt('Nombre del nuevo proyecto','Mi juego');if(!n)return;const p=JSON.parse(localStorage.getItem('mf_projects')||'[]');if(p.includes(n)){toast('Ya existe ese proyecto');return;}p.push(n);localStorage.setItem('mf_projects',JSON.stringify(p));addCustomCard(n);data.customName=n;showEditor('custom');};
$('#importModel').onclick=()=>$('#modelFile').click();
$('#modelFile').addEventListener('change',async e=>{const files=[...(e.target.files||[])];if(!files.length)return;try{await importModelFiles(files);}catch(err){toast(`Importación falló: ${err.message||err}`);}finally{e.target.value='';}});
async function importModelFiles(files){if(data.playing)stopGame();const main=files.find(f=>/\.(glb|gltf)$/i.test(f.name));if(!main)throw new Error('Selecciona un archivo GLB o GLTF');if(files.some(f=>f.size>150*1024*1024))throw new Error('Cada archivo debe pesar menos de 150 MB');const urls=[],cache=new Map(),byName=new Map(files.map(f=>[f.name.toLowerCase(),f]));const loader=new GLTFLoader();loader.manager.setURLModifier(request=>{const path=decodeURIComponent(request.split(/[?#]/)[0]),name=path.split('/').pop().toLowerCase(),asset=byName.get(name);if(!asset)return request;if(!cache.has(asset.name)){const url=URL.createObjectURL(asset);cache.set(asset.name,url);urls.push(url);}return cache.get(asset.name);});try{const buffer=await main.arrayBuffer();const gltf=await new Promise((resolve,reject)=>loader.parse(buffer,'',resolve,reject));const model=new THREE.Group();model.name=main.name.replace(/\.(glb|gltf)$/i,'');model.userData.nodeType='GLTF';model.userData.sourceFile=main.name;model.userData.blobUrls=urls;model.add(gltf.scene);model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});model.updateWorldMatrix(true,true);let bounds=new THREE.Box3().setFromObject(model);if(!bounds.isEmpty()){const size=bounds.getSize(new THREE.Vector3()),max=Math.max(size.x,size.y,size.z);if(max>10000)throw new Error('El escenario tiene dimensiones fuera de rango');if(max>24)model.scale.setScalar(24/max);model.updateWorldMatrix(true,true);bounds.setFromObject(model);const center=bounds.getCenter(new THREE.Vector3());model.position.x-=center.x;model.position.z-=center.z;model.position.y+=-.56-bounds.min.y;model.updateWorldMatrix(true,true);bounds.setFromObject(model);}state.rootNode.add(model);data.objects.push(model);data.selected=model;const sphere=bounds.getBoundingSphere(new THREE.Sphere());state.focusTarget.set(0,Math.max(0,sphere.center.y),0);state.spherical.radius=THREE.MathUtils.clamp(Math.max(4,sphere.radius*2.2),4,40);state.spherical.phi=1.1;state.orbit=null;state.pinch=null;state.drag=null;state.activePointers.clear();updateCamera();updateTree();updateInspector();refreshOutline();syncGizmo();updateFileList(files.map(f=>f.name));scheduleSceneSave();toast(`Escena importada y encuadrada: ${model.name}`);}catch(err){urls.forEach(URL.revokeObjectURL);throw err;}}
function updateFileList(names=[]){renderFileList();}
const SCENE_PRESETS=[{id:'fps',name:'First Person Starter'},{id:'tps',name:'Third Person Starter'},{id:'testyard',name:'Patio de pruebas'},{id:'room',name:'Habitación de prueba'}];
function projectScope(){return data.project==='custom'?`custom:${data.customName||'Mi juego'}`:data.project;}
const fsProject=()=>encodeURIComponent(projectScope());
const projectIndexKey=()=>`mf_project_files/${fsProject()}/index.json`;
const sceneFilePath=id=>`scenes/${fsProject()}/${encodeURIComponent(id)}.json`;
const scriptFilePath=(sceneId,nodeId)=>`scripts/${fsProject()}/${encodeURIComponent(sceneId)}/${encodeURIComponent(nodeId)}.json`;
function readProjectIndex(){try{return JSON.parse(localStorage.getItem(projectIndexKey())||'{"scenes":[],"openTabs":[],"activeScene":null}');}catch{return {scenes:[],openTabs:[],activeScene:null};}}
function writeProjectIndex(index){localStorage.setItem(projectIndexKey(),JSON.stringify(index));}
function sceneRecords(){const index=readProjectIndex(),entries=[];for(const file of index.scenes||[]){try{const scene=JSON.parse(localStorage.getItem(sceneFilePath(file.id))||'null');if(scene)entries.push({...file,...scene,scene:scene.scene||scene});}catch{}}if(entries.length)return entries;try{let old=JSON.parse(localStorage.getItem('mf_scenes_'+encodeURIComponent(projectScope()))||'[]');if(!old.length)old=JSON.parse(localStorage.getItem('mf_saved_scenes')||'[]').filter(r=>(r.projectScope||r.project)===projectScope());if(!old.length)return[];const migrated=old.map((r,i)=>({...r,id:r.id||`legacy-${i}-${Date.now()}`,projectScope:projectScope(),scene:r.scene||{nodes:[]}}));writeSceneRecords(migrated);return migrated;}catch{return[];}}
function writeSceneRecords(records){const index=readProjectIndex();for(const r of records){const id=r.id||`scene-${Date.now()}`;r.id=id;const payload={id,name:r.name,projectScope:projectScope(),savedAt:r.savedAt||new Date().toISOString(),scene:r.scene||{nodes:[]}};localStorage.setItem(sceneFilePath(id),JSON.stringify(payload));const i=(index.scenes||[]).findIndex(x=>x.id===id);if(i<0)(index.scenes||=[]).push({id,name:r.name});else index.scenes[i]={id,name:r.name};}writeProjectIndex(index);}
function sceneTemplate(name='Nueva escena'){return {nodes:[{objectId:`object-${Date.now()}`,name:'Suelo',type:'Plane',parent:'root',position:[0,-.56,0],rotation:[-Math.PI/2,0,0],scale:[1,1,1],color:0x393e42,scriptPath:null}],modelFiles:[]};}
function renderSceneTabs(){const box=$('#sceneTabs');if(!box)return;box.replaceChildren();const records=sceneRecords();for(const id of data.sceneTabs){const entry=records.find(x=>x.id===id)||{id,name:'Escena'};const tab=document.createElement('button');tab.className='resource-tab scene-tab'+(id===data.sceneId?' active':'');tab.title=entry.name;const label=document.createElement('span');label.textContent=entry.name;const close=document.createElement('span');close.className='scene-tab-close';close.textContent='×';close.title='Cerrar pestaña';tab.append(label,close);tab.onclick=e=>{if(e.target===close){e.stopPropagation();closeSceneTab(id);}else switchSceneTab(id);};box.append(tab);}}
function renderSceneList(){const box=$('#sceneEntries');if(!box)return;box.replaceChildren();const saved=sceneRecords();if(!saved.length){const note=document.createElement('small');note.className='scene-note';note.textContent='La carpeta scenes de este proyecto está vacía.';box.append(note);return;}for(const scene of saved){const row=document.createElement('div');row.className='scene-entry';const title=document.createElement('strong');title.textContent=scene.name;const actions=document.createElement('div');actions.className='scene-actions';const open=document.createElement('button');open.className='small-btn';open.textContent='Abrir';open.onclick=()=>openSceneTab(scene.id);const insert=document.createElement('button');insert.className='small-btn accent';insert.textContent='Instanciar';insert.onclick=()=>instantiateScene(scene);const remove=document.createElement('button');remove.className='small-btn';remove.textContent='×';remove.title='Borrar archivo de escena';remove.onclick=()=>deleteSceneFile(scene.id);actions.append(open,insert,remove);row.append(title,actions);box.append(row);}}
function renderFileList(){const box=$('#fileList');if(!box)return;box.replaceChildren();const scenes=sceneRecords();const scripts=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(`scripts/${fsProject()}/`))scripts.push(key);}const add=(path,label,remove)=>{const row=document.createElement('div');row.className='file-entry';const name=document.createElement('span');name.textContent=label;const del=document.createElement('button');del.className='file-delete';del.textContent='×';del.title=`Borrar ${label}`;del.onclick=remove;row.append(name,del);box.append(row);};const folder=document.createElement('div');folder.className='file-folder';folder.textContent='scenes/';box.append(folder);for(const scene of scenes)add(sceneFilePath(scene.id),`${scene.name}.json`,()=>deleteSceneFile(scene.id));const scriptsFolder=document.createElement('div');scriptsFolder.className='file-folder';scriptsFolder.textContent='scripts/';box.append(scriptsFolder);for(const path of scripts)add(path.split('/').slice(-1)[0],path.split('/').slice(-1)[0]+'.json',()=>deleteScriptFile(path));if(!scenes.length&&!scripts.length){const note=document.createElement('small');note.textContent='No hay archivos guardados.';box.append(note);}}
function saveNodeScript(node){if(!data.sceneId||!node)return;node.userData.sceneObjectId ||= `object-${crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2)}`;const path=scriptFilePath(data.sceneId,node.userData.sceneObjectId);const payload={scriptText:node.userData.scriptText||'',shaderCode:node.userData.shaderCode||'',vertexShader:node.userData.vertexShader||''};try{localStorage.setItem(path,JSON.stringify(payload));if(data.tab==='files')renderFileList();}catch{toast('No hay espacio para guardar el script');} }
function persistActiveScene(){if(!data.sceneId||!state.rootNode)return;const previous=sceneRecords().find(x=>x.id===data.sceneId),entry={id:data.sceneId,name:previous?.name||$('#projectName').textContent||'Escena',project:data.project,projectScope:projectScope(),scene:serializeScene(),savedAt:new Date().toISOString()};try{for(const o of data.objects)if(o.userData.scriptText||o.userData.shaderCode||o.userData.vertexShader)saveNodeScript(o);writeSceneRecords([entry]);renderSceneTabs();renderSceneList();renderFileList();const index=readProjectIndex();index.openTabs=[...data.sceneTabs];index.activeScene=data.sceneId;writeProjectIndex(index);}catch{toast('No hay espacio para guardar la escena');}}
function renderSceneListAndFiles(){renderSceneList();renderFileList();}
function setDock(tab){data.tab=tab;for(const [key,id]of [['scene','nodeList'],['scenes','sceneList'],['files','fileList']])$('#'+id).classList.toggle('hidden',key!==tab);$('#treeFilter').parentElement.classList.toggle('hidden',tab!=='scene');document.querySelectorAll('.tree .dock-tab[data-dock]').forEach(b=>b.classList.toggle('active',b.dataset.dock===tab));if(tab==='scenes')renderSceneList();if(tab==='files')renderFileList();}
function clearSceneForRestore(){for(const child of [...state.rootNode.children])state.rootNode.remove(child);data.objects=[];state.outlineNodes=[];}
function createGround(){const floor=new THREE.Mesh(new THREE.PlaneGeometry(80,80),new THREE.MeshStandardMaterial({color:0x393e42,roughness:.92}));floor.name='Suelo';floor.userData.nodeType='Plane';floor.rotation.x=-Math.PI/2;floor.position.y=-.56;floor.receiveShadow=true;state.rootNode.add(floor);data.objects.push(floor);return floor;}
function loadSavedScene(entry){if(!entry?.scene?.nodes){toast('El archivo de escena no es válido');return;}clearSceneForRestore();const map=new Map([['root',state.rootNode]]),pending=[...entry.scene.nodes];let pass=0;while(pending.length&&pass++<entry.scene.nodes.length+10){let progress=false;for(let i=pending.length-1;i>=0;i--){const r=pending[i];if(r.type==='GLTF'){pending.splice(i,1);continue;}const parent=map.get(r.parentId)||map.get(r.parent)||((!r.parent||r.parent==='root')?state.rootNode:null);if(!parent)continue;const node=makeFromRecord(r,parent);node.userData.sceneObjectId=r.objectId||`object-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;node.userData.instanceSceneId=r.instanceSceneId||null;node.userData.instanceSceneName=r.instanceSceneName||'';if(r.scriptPath){try{const script=JSON.parse(localStorage.getItem(r.scriptPath)||'null');if(script)Object.assign(node.userData,script);}catch{}}else if(r.script)node.userData.scriptText=r.script||'';if(node.userData.shaderCode||node.userData.vertexShader)applyShader(node);map.set(r.objectId||r.name,node);map.set(r.name,node);pending.splice(i,1);progress=true;}if(!progress)break;}if(!data.objects.length)createGround();data.selected=data.objects.find(o=>o.name.startsWith('Player'))||data.objects.find(o=>o.name!=='Suelo')||data.objects[0];state.focusTarget.copy(data.selected?.getWorldPosition(new THREE.Vector3())||new THREE.Vector3());state.spherical.radius=8;updateTree();updateInspector();refreshOutline();syncGizmo();$('#projectName').textContent=data.customName||data.project.toUpperCase();renderSceneTabs();setDock('scene');toast(pending.length?'Escena abierta; algunos nodos no se pudieron restaurar':'Escena abierta.');}
function createSceneTab(name,useCurrentScene=false){persistActiveScene();const id=`scene-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;data.sceneId=id;const entry={id,name,project:data.project,projectScope:projectScope(),scene:useCurrentScene?serializeScene():sceneTemplate(name),savedAt:new Date().toISOString()};writeSceneRecords([entry]);if(useCurrentScene)for(const o of data.objects)if(o.userData.scriptText||o.userData.shaderCode||o.userData.vertexShader)saveNodeScript(o);data.sceneTabs.push(id);loadSavedScene(entry);const index=readProjectIndex();index.openTabs=[...data.sceneTabs];index.activeScene=id;writeProjectIndex(index);renderSceneTabs();}
function initializeSceneTabs(){const index=readProjectIndex(),saved=sceneRecords(),valid=(index.openTabs||[]).filter(id=>saved.some(s=>s.id===id));data.sceneTabs=valid;const active=valid.includes(index.activeScene)?index.activeScene:valid[0];if(active){data.sceneId=active;loadSavedScene(saved.find(s=>s.id===active));}else{data.sceneId=null;data.sceneTabs=[];createSceneTab(data.customName||`${data.project.toUpperCase()} Scene`,true);}renderSceneTabs();renderSceneListAndFiles();}
function switchSceneTab(id){if(id===data.sceneId)return;persistActiveScene();const rec=sceneRecords().find(x=>x.id===id);if(!rec)return;if(!data.sceneTabs.includes(id))data.sceneTabs.push(id);data.sceneId=id;loadSavedScene(rec);const index=readProjectIndex();index.openTabs=[...data.sceneTabs];index.activeScene=id;writeProjectIndex(index);renderSceneTabs();}
function openSceneTab(id){if(!data.sceneTabs.includes(id))data.sceneTabs.push(id);switchSceneTab(id);}
function closeSceneTab(id){if(data.sceneId===id)persistActiveScene();data.sceneTabs=data.sceneTabs.filter(x=>x!==id);if(data.sceneId===id){const next=data.sceneTabs.at(-1);if(next){data.sceneId=next;const r=sceneRecords().find(x=>x.id===next);if(r)loadSavedScene(r);}else{data.sceneId=null;createSceneTab('Nueva escena');}}const index=readProjectIndex();index.openTabs=[...data.sceneTabs];index.activeScene=data.sceneId;writeProjectIndex(index);renderSceneTabs();}
function deleteSceneFile(id){if(!confirm('¿Borrar este archivo de escena y sus scripts guardados?'))return;localStorage.removeItem(sceneFilePath(id));const scriptPrefix=`scripts/${fsProject()}/${encodeURIComponent(id)}/`;const scriptKeys=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(scriptPrefix))scriptKeys.push(key);}scriptKeys.forEach(key=>localStorage.removeItem(key));const index=readProjectIndex();index.scenes=(index.scenes||[]).filter(x=>x.id!==id);index.openTabs=(index.openTabs||[]).filter(x=>x!==id);if(index.activeScene===id)index.activeScene=null;writeProjectIndex(index);if(data.sceneId===id){data.sceneTabs=index.openTabs;const next=data.sceneTabs.at(-1);if(next){data.sceneId=next;const entry=sceneRecords().find(x=>x.id===next);if(entry)loadSavedScene(entry);}else{data.sceneId=null;createSceneTab('Nueva escena');}}renderSceneTabs();renderSceneListAndFiles();toast('Archivo de escena borrado');}
function deleteScriptFile(path){if(!confirm('¿Borrar este archivo de script?'))return;const objectId=decodeURIComponent(path.split('/').at(-1).replace(/\.json$/,''));localStorage.removeItem(path);for(const node of data.objects)if(node.userData.sceneObjectId===objectId){node.userData.scriptText='';node.userData.shaderCode='';node.userData.vertexShader='';applyShader(node);}persistActiveScene();renderFileList();toast('Archivo de script borrado');}
function renderInstancePicker(){const box=$('#instanceSceneChoices');box.replaceChildren();const records=sceneRecords().filter(x=>x.id!==data.sceneId);if(!records.length){const note=document.createElement('small');note.textContent='Guarda o crea otra escena para poder instanciarla.';box.append(note);return;}for(const entry of records){const button=document.createElement('button');button.className='node-choice';button.textContent=entry.name;button.onclick=()=>{instantiateScene(entry);$('#instanceScenePicker').classList.add('hidden');};box.append(button);}}
function instantiateScene(entry){if(!entry?.scene?.nodes)return;const attach=data.selected||state.rootNode;const recs=entry.scene.nodes.filter(r=>r.type!=='GLTF'),map=new Map([['root',attach]]),roots=[];for(const rec of recs){const parent=map.get(rec.parentId)||map.get(rec.parent)||attach;const node=makeFromRecord({...rec,name:rec.name},parent);node.userData.sceneObjectId=`instance-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;if(rec.scriptPath){try{Object.assign(node.userData,JSON.parse(localStorage.getItem(rec.scriptPath)||'{}'));}catch{}}if(node.userData.shaderCode||node.userData.vertexShader)applyShader(node);const key=rec.objectId||rec.name;map.set(key,node);map.set(rec.name,node);if((!rec.parentId||rec.parentId==='root')&&(!rec.parent||rec.parent==='root')){node.userData.instanceSceneId=entry.id;node.userData.instanceSceneName=entry.name;roots.push(node);}}selectObject(roots[0]||attach);updateTree();refreshOutline();persistActiveScene();toast(`Escena instanciada: ${entry.name}`);}
