function serializeScene(){const nodes=[];for(const o of data.objects)if(!o.userData.helper&&o.userData.nodeType!=='GLTF')o.userData.sceneObjectId ||= `object-${crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2)}`;for(const o of data.objects){if(o.userData.helper||o.userData.nodeType==='GLTF')continue;const parent=o.parent;nodes.push({objectId:o.userData.sceneObjectId,name:o.name,type:o.userData.nodeType||'Node3D',parentId:parent===state.rootNode?'root':parent?.userData?.sceneObjectId||'root',parent:parent===state.rootNode?'root':parent?.name||'root',position:o.position.toArray(),rotation:o.rotation.toArray(),scale:o.scale.toArray(),color:o.material?.color?.getHex()??0x6ee5cc,scriptPath:scriptFilePath(data.sceneId,o.userData.sceneObjectId),instanceSceneId:o.userData.instanceSceneId||null,instanceSceneName:o.userData.instanceSceneName||'',image:o.userData.imageDataURL||''});}return {nodes,modelFiles:data.objects.filter(o=>o.userData.nodeType==='GLTF').map(o=>o.userData.sourceFile||o.name)};}
