function addGodotNode(type){const parent=data.selected||state.rootNode;let node;const pos=[0,1,0],colors={MeshInstance3D:0x50e0c0,SphereMesh:0x9b8dff,CapsuleMesh:0xffb86b,CylinderMesh:0x68a9dc,PlaneMesh:0x78866d};if(['MeshInstance3D','SphereMesh','CapsuleMesh','CylinderMesh','PlaneMesh','CollisionShape3D'].includes(type)){const geo=type==='SphereMesh'?new THREE.SphereGeometry(.6,24,16):type==='CapsuleMesh'?new THREE.CapsuleGeometry(.35,.8,5,12):type==='CylinderMesh'?new THREE.CylinderGeometry(.5,.5,1,24):type==='PlaneMesh'?new THREE.PlaneGeometry(2,2):type==='CollisionShape3D'?new THREE.BoxGeometry(1,1,1):new THREE.BoxGeometry(1,1,1);node=new THREE.Mesh(geo,mat(type==='CollisionShape3D'?0x76b9ff:(colors[type]||0x50e0c0)));node.castShadow=true;node.receiveShadow=true;node.position.set(...pos);node.name=type==='MeshInstance3D'?'MeshInstance3D':type;node.userData.nodeType=type;if(type==='CollisionShape3D'){node.material.transparent=true;node.material.opacity=.22;node.userData.collisionPlaceholder=true;}}else if(type==='Camera3D'){node=new THREE.Group();node.name='Camera3D';node.userData.nodeType=type;node.position.set(0,1.8,3);const camera=new THREE.PerspectiveCamera(50,1,.1,100);camera.name='Camera';camera.userData.helper=true;node.add(camera);const marker=new THREE.Mesh(new THREE.BoxGeometry(.35,.23,.28),new THREE.MeshBasicMaterial({color:0xffcf66,wireframe:true}));marker.userData.helper=true;marker.raycast=()=>{};node.add(marker);}else if(type.includes('Light3D')){node=new THREE.Group();node.name=type;node.userData.nodeType=type;node.position.set(0,2,0);const color=0xffedcf;const light=type==='DirectionalLight3D'?new THREE.DirectionalLight(color,2):type==='SpotLight3D'?new THREE.SpotLight(color,35,20,Math.PI/6):new THREE.PointLight(color,18,20);light.name=type;light.userData.helper=true;node.add(light);if(type==='DirectionalLight3D')light.position.set(2,3,1);const marker=new THREE.Mesh(new THREE.SphereGeometry(.14,12,8),new THREE.MeshBasicMaterial({color:0xffdf79}));marker.userData.helper=true;marker.raycast=()=>{};node.add(marker);}else{node=new THREE.Group();node.name=type;node.userData.nodeType=type;node.position.set(...pos);if(['StaticBody3D','RigidBody3D','CharacterBody3D'].includes(type)){const shape=new THREE.Mesh(new THREE.BoxGeometry(1,1,1),new THREE.MeshBasicMaterial({color:0x6fa8ff,wireframe:true,transparent:true,opacity:.45}));shape.userData.helper=true;shape.raycast=()=>{};node.add(shape);node.userData.physicsNote='Placeholder de nodo: no hay simulación de cuerpo física aún';}}
  node.userData.nodeType=type;if(!node.parent)parent.add(node);data.objects.push(node);selectObject(node);toast(`Nodo ${type} añadido`);}
