function highlightCode(text,mode='lua'){const escaped=String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const tokens=mode==='glsl'?/\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:void|float|int|bool|vec[234]|mat[234]|uniform|varying|attribute|precision|highp|mediump|lowp|if|else|for|return|true|false)\b|\b\d+(?:\.\d+)?\b|\b[a-zA-Z_]\w*(?=\s*\()/g:/--[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:local|function|end|if|then|else|elseif|for|while|do|return|true|false|nil|and|or|not|in)\b|\b\d+(?:\.\d+)?\b|\b[a-zA-Z_]\w*(?=\s*\()/g;return escaped.replace(tokens,token=>{const e=token.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const cls=token.startsWith('--')||token.startsWith('//')||token.startsWith('/*')?'tok-comment':/^['"]/.test(token)?'tok-string':/^\d/.test(token)?'tok-number':/^(local|function|end|if|then|else|elseif|for|while|do|return|true|false|nil|and|or|not|in|void|float|int|bool|vec[234]|mat[234]|uniform|varying|attribute|precision|highp|mediump|lowp)$/.test(token)?'tok-keyword':'tok-function';return `<span class="${cls}">${e}</span>`;}).replace(/\n$/,'\n ');}
function syncHighlight(editorId,preId,mode){const textarea=$('#'+editorId),pre=$('#'+preId);if(!textarea||!pre)return;pre.innerHTML=highlightCode(textarea.value,mode)+'\n';pre.scrollTop=textarea.scrollTop;pre.scrollLeft=textarea.scrollLeft;}
$('#scriptOverlayEditor').addEventListener('input',e=>{if(state.scriptTarget){if(state.codeMode==='glsl'){if(state.codeStage==='vertex')state.scriptTarget.userData.vertexShader=e.target.value;else state.scriptTarget.userData.shaderCode=e.target.value;}else state.scriptTarget.userData.scriptText=e.target.value;}syncHighlight('scriptOverlayEditor','scriptOverlayHighlight',state.codeMode);syncCodeEditors(state.scriptTarget);saveNodeScript(state.scriptTarget);});$('#scriptOverlayEditor').addEventListener('scroll',()=>syncHighlight('scriptOverlayEditor','scriptOverlayHighlight',state.codeMode));$('#scriptVertexEditor').addEventListener('scroll',()=>syncHighlight('scriptVertexEditor','scriptVertexHighlight','glsl'));document.querySelectorAll('[data-code-mode]').forEach(b=>b.onclick=()=>setCodeMode(b.dataset.codeMode,state.scriptTarget));document.querySelectorAll('[data-code-stage]').forEach(b=>b.onclick=()=>{state.codeStage=b.dataset.codeStage;setCodeMode('glsl',state.scriptTarget);});$('#scriptVertexEditor').addEventListener('input',e=>{if(state.scriptTarget){state.scriptTarget.userData.vertexShader=e.target.value;saveNodeScript(state.scriptTarget);}syncHighlight('scriptVertexEditor','scriptVertexHighlight','glsl');});for(const eventName of ['pointerdown','pointermove','pointerup','pointercancel','wheel'])$('#scriptOverlay').addEventListener(eventName,e=>e.stopPropagation());$('#runOverlayScript').onclick=()=>applySelectedCode(state.scriptTarget||data.selected);$('#closeScriptOverlay').onclick=closeScriptMode;$('#scriptImageFile').onchange=e=>{const f=e.target.files?.[0];if(f&&state.scriptTarget)applyImageFile(f,state.scriptTarget).catch(err=>toast(err.message));e.target.value='';};
document.querySelectorAll('.main-modes .mode-tab').forEach(b=>b.onclick=()=>{const mode=b.dataset.tool;if(mode==='script'){openScriptMode();return;}if(mode==='3d'){closeScriptMode();document.querySelectorAll('.main-modes .mode-tab').forEach(x=>x.classList.toggle('selected',x===b));if(data.playing)stopGame();return;}closeScriptMode();document.querySelectorAll('.main-modes .mode-tab').forEach(x=>x.classList.toggle('selected',x===b));if(data.playing)stopGame();else startGame();});
document.querySelectorAll('.gizmo-mode').forEach(b=>b.onclick=()=>{document.querySelectorAll('.gizmo-mode').forEach(x=>x.classList.toggle('active',x===b));setGizmoMode(b.dataset.mode);});
$('#toggleGrid').onclick=()=>{state.grid.visible=!state.grid.visible;$('#toggleGrid').classList.toggle('active',state.grid.visible);};$('#toggleOutline').onclick=()=>{state.outlineEnabled=!state.outlineEnabled;$('#toggleOutline').classList.toggle('active',state.outlineEnabled);refreshOutline();};
$('#treeFilter').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('#nodeList .node-item').forEach(n=>{n.hidden=!n.textContent.toLowerCase().includes(q);});});
document.querySelectorAll('[data-dock]').forEach(b=>b.onclick=()=>{setDock(b.dataset.dock);if(b.dataset.dock==='files')renderFileList();});document.addEventListener('visibilitychange',()=>{if(document.hidden)persistActiveScene();});
async function checkForUpdate(automatic=false){
  if(!Capacitor.isNativePlatform()){toast('Actualizaciones automáticas disponibles en Android');return;}
  try{
    const res=await fetch('https://api.github.com/repos/blopex67-cloud/MobiForge3D/releases/latest',{headers:{Accept:'application/vnd.github+json'}});
    if(!res.ok)throw new Error('No se pudo consultar la versión');
    const rel=await res.json(),latest=String(rel.tag_name||'').replace(/^v/i,''),current=APP_VERSION;
    const n=s=>s.split('.').map(x=>parseInt(x,10)||0),a=n(latest),b=n(current),newer=a.some((v,i)=>v>(b[i]||0)&&a.slice(0,i).every((x,j)=>x===(b[j]||0)));
    if(!newer){if(!automatic)toast('La app está actualizada');return;}
    const asset=(rel.assets||[]).find(x=>x.name==='MobiForge3D.apk');if(!asset)throw new Error('No se encontró el APK de actualización');
    if(!window.confirm(`Hay una actualización ${latest}. Descargar e instalar ahora? Android pedirá confirmar la instalación.`))return;
    toast('Descargando actualización…');await AppUpdater.install({url:asset.browser_download_url,version:latest});
  }catch(err){toast(err?.message||'No se pudo actualizar');}
}
$('#checkUpdates').onclick=()=>checkForUpdate(false);
$('#checkUpdatesHome').onclick=()=>checkForUpdate(false);
setTimeout(()=>checkForUpdate(true),1800);
function applyLuaCommand(msg){const target=state.luaTarget;if(!target)return;if(msg.command==='outline_scale'){const scale=Number(msg.values?.[0]);if(!Number.isFinite(scale))return;for(const n of state.outlineNodes)n.scale.setScalar(THREE.MathUtils.clamp(scale,1.001,1.3));state.outlineScale=scale;return;}const values=(msg.values||[]).map(Number);if(values.some(x=>!Number.isFinite(x)))return;const [x=0,y=0,z=0]=values;if(msg.command==='material_property'){const v=msg.value;if(msg.property==='outline_enabled'){state.outlineEnabled=!!v;refreshOutline(target,state.outlineColor,state.outlineScale||1.035);}else if(msg.property==='outline_color'&&Array.isArray(v)){state.outlineColor=new THREE.Color(v[0]||0,v[1]||0,v[2]||0);refreshOutline(target,state.outlineColor,state.outlineScale||1.035);}else if(msg.property==='outline_width'&&Number.isFinite(Number(v))){state.outlineScale=1+THREE.MathUtils.clamp(Number(v),.001,.25);refreshOutline(target,state.outlineColor,state.outlineScale);}else if(msg.property==='emission_enabled'||msg.property==='emission_energy'){target.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!m)continue;if(msg.property==='emission_enabled'){if(v){if(m.emissive)m.emissive.set(0xffffff);m.emissiveIntensity=Math.max(m.emissiveIntensity||0,1);}else if(m.emissiveIntensity)m.emissiveIntensity=0;}else m.emissiveIntensity=THREE.MathUtils.clamp(Number(v)||0,0,10);m.needsUpdate=true;}});}return;}if(msg.command==='outline_scale'){for(const n of state.outlineNodes)n.scale.setScalar(THREE.MathUtils.clamp(x,1.001,1.3));state.outlineScale=x;return;}if(msg.command==='move')target.position.add(new THREE.Vector3(x,y,z));else if(msg.command==='set_position')target.position.set(x,y,z);else if(msg.command==='rotate'){target.rotation.x+=x;target.rotation.y+=y;target.rotation.z+=z;}else if(msg.command==='set_scale')target.scale.set(THREE.MathUtils.clamp(x,.01,100),THREE.MathUtils.clamp(y,.01,100),THREE.MathUtils.clamp(z,.01,100));syncGizmo();scheduleSceneSave();}
function executeLua(source,target,automatic=false,live=false){if(state.luaWorker)state.luaWorker.terminate();setWorker();state.luaTarget=target;state.luaLive=live;state.luaWaiting=true;const b=$('#runOverlayScript'),result=$('#luaResult');if(result){result.classList.remove('lua-error');result.removeAttribute('title');delete result.dataset.errorLine;}if(b)b.disabled=true;if(result)result.textContent='Ejecutando Lua…';clearTimeout(state.luaTimer);state.luaTimer=setTimeout(()=>{state.luaWorker?.terminate();state.luaWorker=null;state.luaLive=false;state.luaWaiting=false;if(b)b.disabled=false;if(result)result.textContent='Tiempo agotado; ejecución detenida.';if(!automatic)toast('Lua detenido por límite de tiempo');},1500);state.luaWorker.postMessage({type:'run',source,nodeName:target?.name||'Node3D',persistent:live});}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopRender();}else if(!editor.classList.contains('hidden'))startRender();});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&data.playing)stopGame();});
